#!/usr/bin/env bash
# Bring new upstream commits into this fork as a single patch.
#
# Upstream history is not merged: GitHub refuses pushes from the Actions token
# that contain commits touching .github/workflows, and upstream edits its
# workflows. Instead the diff between the last synced upstream commit and the
# new one is applied with a 3-way fallback, skipping paths the fork owns:
#   .github/workflows  - the fork keeps its own workflows
#   module.json        - regenerated by tools/fork/apply-fork-manifest.mjs
#   README.md          - the fork's README
#
# Leaves the result staged (nothing is committed) and reports via
# $GITHUB_OUTPUT (or stdout):
#   status=up-to-date | no-changes | synced | conflict | history-rewritten
#   upstream_commit, previous_commit, version, conflicts (comma-separated)
#
# Env overrides: UPSTREAM_REF (branch/tag), UPSTREAM_URL (fetch URL, for tests).
set -euo pipefail

CONFIG=fork/upstream.json
OUT=${GITHUB_OUTPUT:-/dev/stdout}
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

json() { node -e "process.stdout.write(String(require('./$CONFIG')['$1']))"; }

REPO=$(json repository)
REF=${UPSTREAM_REF:-$(json ref)}
LAST=$(json syncedCommit)
URL=${UPSTREAM_URL:-https://github.com/$REPO}

output() { echo "$1=$2" >> "$OUT"; }

if [ -n "$(git status --porcelain --untracked-files=no)" ]; then
  echo "Working tree is not clean; refusing to sync." >&2
  exit 1
fi

git fetch --quiet --no-tags "$URL" "$REF"
NEW=$(git rev-parse FETCH_HEAD)
output upstream_commit "$NEW"
output previous_commit "$LAST"

if [ "$NEW" = "$LAST" ]; then
  output status up-to-date
  echo "Already in sync with $REPO@$REF ($NEW)."
  exit 0
fi

if ! git cat-file -e "$LAST^{commit}" 2>/dev/null; then
  git fetch --quiet --no-tags "$URL" "$LAST" || true
fi
if ! git merge-base --is-ancestor "$LAST" "$NEW" 2>/dev/null; then
  output status history-rewritten
  echo "Upstream $REF no longer contains the last synced commit $LAST." >&2
  exit 3
fi

EXCLUDES=(':(exclude).github/workflows' ':(exclude)module.json' ':(exclude)README.md')
git diff --binary --full-index "$LAST" "$NEW" -- . "${EXCLUDES[@]}" > "$WORK/upstream.patch"
git show "$LAST:module.json" > "$WORK/upstream-module.old.json"
git show "$NEW:module.json" > "$WORK/upstream-module.json"

if [ ! -s "$WORK/upstream.patch" ] && cmp -s "$WORK/upstream-module.old.json" "$WORK/upstream-module.json"; then
  # Upstream only touched fork-owned paths (workflows/README): record and stop.
  node -e "
    const fs = require('fs');
    const c = JSON.parse(fs.readFileSync('$CONFIG', 'utf8'));
    c.syncedCommit = '$NEW';
    fs.writeFileSync('$CONFIG', JSON.stringify(c, null, 2) + '\n');
  "
  git add "$CONFIG"
  output status no-changes
  echo "Upstream changes only touch fork-owned files; recorded $NEW."
  exit 0
fi

if [ -s "$WORK/upstream.patch" ]; then
  if ! git apply --3way --index --whitespace=nowarn "$WORK/upstream.patch"; then
    CONFLICTS=$(git diff --name-only --diff-filter=U | paste -sd, -)
    output status conflict
    output conflicts "${CONFLICTS:-unknown}"
    echo "Upstream patch did not apply cleanly. Conflicts: ${CONFLICTS:-unknown}" >&2
    exit 4
  fi
fi

VERSION=$(node tools/fork/apply-fork-manifest.mjs \
  --upstream "$WORK/upstream-module.json" --current module.json --out module.json --bump | tail -1)
if [ -x node_modules/.bin/prettier ]; then node_modules/.bin/prettier --write module.json > /dev/null; fi

node -e "
  const fs = require('fs');
  const c = JSON.parse(fs.readFileSync('$CONFIG', 'utf8'));
  c.syncedCommit = '$NEW';
  fs.writeFileSync('$CONFIG', JSON.stringify(c, null, 2) + '\n');
"
git add module.json "$CONFIG"

output status synced
output version "$VERSION"
echo "Applied upstream $LAST..$NEW; fork version $VERSION."
